mc.sort()

# Reachability
n = len(mc)
reach = [[False] * n for _ in range(n)]
for i in range(n):
    reach[i][i] = True
    for j in range(n):
        if mc[j] == mc[i] - p or mc[j] == mc[i] - q:
            reach[i][j] = True

# Floyd-Warshall
for k in range(n):
    for i in range(n):
        for j in range(n):
            if reach[i][k] and reach[k][j]:
                reach[i][j] = True

# The poset is: m_i <= m_j if reach[j][i] is True.
# Let's count the number of down-sets of this poset.
# A down-set is a set S such that if j in S and i < j (i.e., reach[j][i]), then i in S.
# This is equivalent to: if j in S, then all i such that reach[j][i] is True must be in S.
# This is a classic problem. Since n=95, we can't use bitmask.
# But let's see the structure of the poset.
# It's a set of nodes, and for each node j, we have a set of predecessors {i | reach[j][i]}.
# Because reach[j][i] means i is reachable from j, and the edges are only to smaller values,
# this is a DAG.

# Let's find the number of down-sets of this poset.
# Since n is small, maybe we can use a recursive approach with memoization?
# But we need to represent the state.
# A down-set is a subset of {0, 1, ..., n-1}.
# This is still hard. Let's try to see if the poset is a series-parallel graph or something simple.

# Let's first see the structure.
for i in range(n):
    preds = [j for j in range(n) if reach[i][j]]
    print(f"m_{i} ({mc[i]}) has predecessors: {preds}")

# Let's see if it's a disjoint union of components.
# Two nodes are in the same component if they are reachable from each other?
# No, that's for an undirected graph.
# For a poset, we can look at the components of the underlying undirected graph.
# The underlying undirected graph has an edge between i and j if reach[i][j] or reach[j][i].
adj = [[] for _ in range(n)]
for i in range(n):
    for j in range(n):
        if i != j and (reach[i][j] or reach[j][i]):
            adj[i].append(j)

visited = [False] * n
components = []
for i in range(n):
    if not visited[i]:
        comp = []
        q = [i]
        visited[i] = True
        while q:
            u = q.pop(0)
            comp.append(u)
            for v in adj[u]:
                if not visited[v]:
                    visited[v] = True
                    q.append(v)
        components.append(comp)

print(f"Number of components: {len(components)}")
for i, comp in enumerate(components):
    print(f"Component {i}: {comp}")

def fib(n):
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a

